const ticker=document.getElementById('ticker'),pause=document.getElementById('pause'),reduce=matchMedia('(prefers-reduced-motion: reduce)');function syncPause(){const system=reduce.matches||document.body.classList.contains('motion-off'),paused=system||ticker.classList.contains('paused');pause.disabled=system;pause.setAttribute('aria-pressed',String(paused));pause.textContent=system?'Motion off':paused?'Play':'Pause'}pause.addEventListener('click',()=>{ticker.classList.toggle('paused');syncPause()});reduce.addEventListener('change',syncPause);syncPause();const motionButtons=[...document.querySelectorAll('.motion-toggle')];function syncMotion(){const on=reduce.matches||document.body.classList.contains('motion-off');for(const button of motionButtons){button.disabled=reduce.matches;button.setAttribute('aria-pressed',String(on));button.textContent=reduce.matches?'Reduced motion: system setting':on?'Reduce motion: on':'Reduce motion: off'}}let framePending=false;const ribbon=document.querySelector('.ribbon');const visuals=[...document.querySelectorAll('.project-art svg')];function updateDepth(){framePending=false;const off=reduce.matches||document.body.classList.contains('motion-off');const hero=document.querySelector('.hero');const heroRect=hero.getBoundingClientRect();ribbon.style.setProperty('--ribbon-shift',off?'0px':Math.max(-35,Math.min(35,-heroRect.top*.07))+'px');for(const visual of visuals){const rect=visual.parentElement.getBoundingClientRect();if(rect.bottom<0||rect.top>innerHeight)continue;const progress=Math.max(-1,Math.min(1,(innerHeight/2-(rect.top+rect.height/2))/(innerHeight/2+rect.height/2)));visual.style.setProperty('--art-shift',off?'0px':(-progress*16)+'px');visual.style.setProperty('--art-scale',off?'1':String(1+progress*.04))}}addEventListener('scroll',()=>{if(!framePending){framePending=true;requestAnimationFrame(updateDepth)}},{passive:true});motionButtons.forEach(button=>button.addEventListener('click',()=>{document.body.classList.toggle('motion-off');syncMotion();syncPause();updateDepth()}));reduce.addEventListener('change',()=>{syncMotion();updateDepth()});if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('in-view',entry.isIntersecting)),{threshold:.15});document.querySelectorAll('.section-head,.project,.contact').forEach(element=>observer.observe(element))}syncMotion();updateDepth();document.querySelectorAll('.menu-panel a').forEach(a=>a.addEventListener('click',()=>document.querySelector('.menu').open=false));document.addEventListener('keydown',event=>{const menu=document.querySelector('.menu');if(event.key==='Escape'&&menu.open){menu.open=false;menu.querySelector('summary').focus()}});
